 112	    throw new GatewayError("bad-target", `configuration must be a JSON object; got ${describe(value)}`);
 113	  }
 114	  const record = value as Record<string, unknown>;
 115	  for (const key of Object.keys(record)) {
 116	    if (key !== "default" && key !== "contracts") {
 117	      throw new GatewayError("bad-target", `configuration has no key ${JSON.stringify(key)}`);
 118	    }
 119	  }
 120	  const raw = record["contracts"];
 121	  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
 122	    throw new GatewayError("bad-target", `configuration "contracts" must be an object; got ${describe(raw)}`);
 123	  }
 124	  const contracts: Record<string, string> = {};
 125	  for (const [chain, address] of Object.entries(raw as Record<string, unknown>)) {
 126	    if (!CHAIN.test(chain)) {
 127	      throw new GatewayError("bad-target", `configuration chain ${JSON.stringify(chain)} is not a decimal chain id`);
 128	    }
 129	    if (typeof address !== "string" || !ADDRESS.test(address.toLowerCase())) {
 130	      throw new GatewayError(
 131	        "bad-target",
 132	        `configuration address for chain ${chain} must be 0x and 40 hex digits; got ${describe(address)}`,
 133	      );
 134	    }
 135	    contracts[chain] = address.toLowerCase();
 136	  }
 137	  const chains = Object.keys(contracts);
 138	  const only = chains[0];
 139	  if (only === undefined) {
 140	    throw new GatewayError("bad-target", 'configuration "contracts" must name at least one chain');
 141	  }
 142	  /* The default may be left out only when there is nothing to choose between. With two contracts a
 143	     missing default would make `/` mean whichever chain the JSON happened to list first. */
 144	  const fallback = record["default"] ?? (chains.length === 1 ? only : undefined);
 145	  if (fallback === undefined) {
 146	    throw new GatewayError("bad-target", `configuration needs "default" when it names ${chains.length} chains`);
 147	  }
 148	  if (typeof fallback !== "string" || !Object.hasOwn(contracts, fallback)) {
 149	    throw new GatewayError(
 150	      "bad-target",
 151	      `configuration "default" must be one of ${chains.join(", ")}; got ${describe(fallback)}`,
