 163	/**
 164	 * The target of a URL in a pinned build: always one of the configured contracts, whatever the
 165	 * hostname says, which is never read. With one contract the whole path is the resource, so a path
 166	 * of the path form is just a path. With several, the first segment is the chain and nothing else
 167	 * reaches a contract — an unconfigured first segment is a 404 that costs no call.
 168	 */
 169	export function pinnedTarget(url: URL, pins: Pins): Target {
 170	  const params: [string, string][] = [...url.searchParams.entries()];
 171	  const chains = Object.keys(pins.contracts);
 172	  const path = segments(url.pathname);
 173	
 174	  if (chains.length === 1) {
 175	    return { chain: pins.default, address: at(pins, pins.default), resource: trimRoot(path), params };
 176	  }
 177	
 178	  const [first, ...rest] = path;
 179	  if (first === undefined || first === "") {
 180	    // 302, not 308: which chain is the default is a setting, and a cached permanent redirect to the
 181	    // old one would outlive the change in every browser that saw it.
 182	    return {
 183	      chain: pins.default,
 184	      address: at(pins, pins.default),
 185	      resource: [],
 186	      params,
 187	      redirect: `/${pins.default}/${url.search}`,
 188	      redirectStatus: 302,
 189	    };
 190	  }
 191	  if (!Object.hasOwn(pins.contracts, first)) {
 192	    throw new GatewayError("not-found", "no contract at this path");
 193	  }
 194	  const target: Target = { chain: first, address: at(pins, first), resource: trimRoot(rest), params };
 195	  if (rest.length === 0) {
 196	    target.redirect = `/${first}/${url.search}`;
 197	    target.redirectStatus = 308;
 198	  }
 199	  return target;
 200	}
 201	
 202	function at(pins: Pins, chain: string): string {
 203	  const address = pins.contracts[chain];
 204	  if (address === undefined) throw new GatewayError("not-found", "no contract at this path");
 205	  return address;
 206	}
