 208	/** `/` splits to one empty segment; the root is the empty resource. */
 209	function trimRoot(resource: string[]): string[] {
 210	  return resource.length === 1 && resource[0] === "" ? [] : resource;
 211	}
 212	import { HTML_SELECTOR, decodeRequestResult, decodeString, encodeRequest } from "./abi.ts";
 213	import { GatewayError } from "./errors.ts";
 214	import { type GatewayResponse, type Rpc, RpcRevert } from "./ports.ts";
 215	import type { Target } from "./target.ts";
 216	
 217	/**
 218	 * Headers a contract may set on its own response. An allowlist, because the same core runs behind
 219	 * adapters where a contract-chosen `Set-Cookie` or `Clear-Site-Data` would reach past its origin.
 220	 */
 221	const PASSED_HEADERS = new Set([
 222	  "content-type",
 223	  "content-language",
 224	  "content-disposition",
 225	  "content-security-policy",
 226	  "referrer-policy",
 227	  "permissions-policy",
 228	  "cross-origin-opener-policy",
 229	  "cross-origin-embedder-policy",
 230	  "cross-origin-resource-policy",
 231	  "access-control-allow-origin",
 232	  "x-frame-options",
 233	]);
 234	
 235	/** Never cached below the client, and never sniffed into a type the contract did not declare. */
 236	const FIXED_HEADERS: [string, string][] = [
 237	  ["cache-control", "no-store"],
 238	  ["x-content-type-options", "nosniff"],
 239	];
 240	
 241	const HEADER_VALUE = /^[\t\x20-\x7e]*$/;
 242	
 243	function respond(status: number, type: string, body: Uint8Array, extra: [string, string][] = []): GatewayResponse {
 244	  return { status, headers: [["content-type", type], ...extra, ...FIXED_HEADERS], body };
 245	}
 246	
 247	/** Plain text, always: an error body never carries markup built from a URL or a contract. */
 248	export function errorResponse(error: unknown): GatewayResponse {
 249	  const known = error instanceof GatewayError ? error : new GatewayError("upstream", "internal gateway error");
 250	  const body = new TextEncoder().encode(`gw44: ${known.message}\n`);
 251	  return respond(known.status, "text/plain; charset=utf-8", body);
 252	}
