 254	/** An address with no code, or a fallback that returns nothing, answers a call with zero bytes. */
 255	async function call(target: Target, rpc: Rpc, data: string): Promise<Uint8Array> {
 256	  const out = await rpc.call(target.chain, target.address, data);
 257	  if (out.length === 0) throw new GatewayError("not-found", "the address does not serve this resource");
 258	  return out;
 259	}
 260	
 261	async function html(target: Target, rpc: Rpc): Promise<GatewayResponse> {
 262	  const body = decodeString(await call(target, rpc, HTML_SELECTOR));
 263	  if (body.length === 0) throw new GatewayError("not-found", "html() returned an empty document");
 264	  return respond(200, "text/html; charset=utf-8", body);
 265	}
 266	
 267	async function request(target: Target, rpc: Rpc): Promise<GatewayResponse> {
 268	  const data = await call(target, rpc, encodeRequest(target.resource, target.params));
 269	  const result = decodeRequestResult(data);
 270	  // The range a `Response` can be built with; 1xx and 3xx-without-Location are not documents.
 271	  if (result.status < 200 || result.status > 599) {
 272	    throw new GatewayError("bad-response", `contract returned status ${result.status}`);
 273	  }
 274	  let type = "application/octet-stream";
 275	  const extra: [string, string][] = [];
 276	  for (const [rawKey, value] of result.headers) {
 277	    const key = rawKey.toLowerCase();
 278	    // A synthesized response is not content-decoded by the browser; garbage is worse than a 502.
 279	    if (key === "content-encoding" && value.toLowerCase() !== "identity") {
 280	      throw new GatewayError("bad-response", `content-encoding ${value} is not supported`);
 281	    }
 282	    if (!PASSED_HEADERS.has(key) || !HEADER_VALUE.test(value)) continue;
 283	    if (key === "content-type") type = value;
 284	    else extra.push([key, value]);
 285	  }
 286	  const nullBody = result.status === 204 || result.status === 205 || result.status === 304;
 287	  return respond(result.status, type, nullBody ? new Uint8Array() : result.body, extra);
 288	}
 289	
 290	/**
 291	 * The whole gateway: the root is ERC-8244 `html()`, every other path is ERC-5219 `request()`.
 292	 * Never throws; a failure is a response.
 293	 */
 294	export async function resolve(target: Target, rpc: Rpc): Promise<GatewayResponse> {
 295	  try {
 296	    if (!rpc.supports(target.chain)) {
 297	      throw new GatewayError("unknown-chain", `chain ${target.chain} is not configured on this gateway`);
 298	    }
 299	    return await (target.resource.length === 0 ? html(target, rpc) : request(target, rpc));
 300	  } catch (error) {
 301	    if (error instanceof RpcRevert) {
 302	      return errorResponse(new GatewayError("not-found", "the contract does not serve this resource"));
 303	    }
 304	    return errorResponse(error);
 305	  }
 306	}
 307	/** Every failure the gateway can describe to a client; anything else is a bug. */
 308	export type GatewayErrorKind =
 309	  | "bad-target" // the URL names no contract
 310	  | "unknown-chain" // no RPC endpoint is configured for the chain
 311	  | "not-found" // the contract answered, and the answer is "no such resource"
 312	  | "bad-response" // the contract or the RPC returned bytes that do not decode
 313	  | "upstream"; // no configured RPC endpoint produced an answer
 314	
 315	const STATUS: Record<GatewayErrorKind, number> = {
 316	  "bad-target": 400,
 317	  "unknown-chain": 404,
 318	  "not-found": 404,
 319	  "bad-response": 502,
 320	  upstream: 502,
 321	};
 322	
 323	export class GatewayError extends Error {
 324	  readonly kind: GatewayErrorKind;
 325	
 326	  constructor(kind: GatewayErrorKind, message: string) {
 327	    super(message);
 328	    this.name = "GatewayError";
 329	    this.kind = kind;
 330	  }
 331	
 332	  get status(): number {
 333	    return STATUS[this.kind];
 334	  }
 335	}
 336	/** One JSON-RPC `eth_call` against `latest`. The only I/O the core performs. */
 337	export interface Rpc {
 338	  /** False when no endpoint is configured for `chain`; `call` would throw `unknown-chain`. */
 339	  supports(chain: string): boolean;
 340	  /**
 341	   * Returns the call's return data. Throws `RpcRevert` when the EVM reverted, which is an
 342	   * answer, and `GatewayError("upstream")` when no endpoint produced one, which is not.
 343	   */
 344	  call(chain: string, to: string, data: string): Promise<Uint8Array>;
 345	}
 346	
 347	export class RpcRevert extends Error {
 348	  constructor(message = "execution reverted") {
 349	    super(message);
 350	    this.name = "RpcRevert";
 351	  }
 352	}
 353	
 354	export interface GatewayResponse {
 355	  status: number;
 356	  headers: [string, string][];
 357	  body: Uint8Array;
 358	}

