  1	import { GatewayError } from "./errors.ts";
  2	
  3	/** `bytes4(keccak256("html()"))`, ERC-8244. */
  4	export const HTML_SELECTOR = "0x33c34ac3";
  5	/** `bytes4(keccak256("request(string[],(string,string)[])"))`, ERC-5219. */
  6	export const REQUEST_SELECTOR = "0x1374c460";
  7	
  8	const WORD = 32;
  9	const MAX_HEADERS = 64;
 10	const utf8 = new TextEncoder();
 11	
 12	export function hexToBytes(hex: string): Uint8Array {
 13	  if (!/^0x([0-9a-fA-F]{2})*$/.test(hex)) throw new GatewayError("bad-response", "result is not hex");
 14	  const out = new Uint8Array((hex.length - 2) / 2);
 15	  for (let i = 0; i < out.length; i++) out[i] = Number.parseInt(hex.slice(2 + i * 2, 4 + i * 2), 16);
 16	  return out;
 17	}
 18	
 19	export function bytesToHex(bytes: Uint8Array): string {
 20	  let out = "0x";
 21	  for (const b of bytes) out += b.toString(16).padStart(2, "0");
 22	  return out;
 23	}
 24	
 25	function word(n: number): Uint8Array {
 26	  const out = new Uint8Array(WORD);
 27	  new DataView(out.buffer).setUint32(WORD - 4, n);
 28	  return out;
 29	}
 30	
 31	function concat(parts: Uint8Array[]): Uint8Array {
 32	  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
 33	  let at = 0;
 34	  for (const p of parts) {
 35	    out.set(p, at);
 36	    at += p.length;
 37	  }
 38	  return out;
 39	}
 40	
 41	function encodeString(s: string): Uint8Array {
 42	  const data = utf8.encode(s);
 43	  const padded = new Uint8Array(Math.ceil(data.length / WORD) * WORD);
 44	  padded.set(data);
 45	  return concat([word(data.length), padded]);
 46	}
 47	
 48	/** A dynamic array of dynamic items: length, one offset per item, then the items. */
 49	function encodeArray(items: Uint8Array[]): Uint8Array {
 50	  const offsets: Uint8Array[] = [];
 51	  let at = items.length * WORD;
 52	  for (const item of items) {
 53	    offsets.push(word(at));
 54	    at += item.length;
 55	  }
 56	  return concat([word(items.length), ...offsets, ...items]);
 57	}
 58	
 59	function encodePair([key, value]: [string, string]): Uint8Array {
 60	  const k = encodeString(key);
 61	  return concat([word(2 * WORD), word(2 * WORD + k.length), k, encodeString(value)]);
 62	}
 63	
 64	/** Calldata for ERC-5219 `request(string[] resource, KeyValue[] params)`. */
 65	export function encodeRequest(resource: string[], params: [string, string][]): string {
 66	  const r = encodeArray(resource.map(encodeString));
 67	  const p = encodeArray(params.map(encodePair));
 68	  return REQUEST_SELECTOR + bytesToHex(concat([word(2 * WORD), word(2 * WORD + r.length), r, p])).slice(2);
 69	}
 70	
 71	/**
 72	 * Reads ABI words out of bytes a contract chose. Every offset and length is attacker-controlled,
 73	 * so each read is bounds-checked against the buffer and nothing is allocated from a claimed size.
 74	 */
 75	function uint(data: Uint8Array, at: number): number {
 76	  if (!Number.isSafeInteger(at) || at < 0 || at + WORD > data.length) {
 77	    throw new GatewayError("bad-response", "return data is truncated");
 78	  }
 79	  for (let i = at; i < at + WORD - 6; i++) {
 80	    if (data[i] !== 0) throw new GatewayError("bad-response", "return data has an out-of-range word");
 81	  }
 82	  let n = 0;
 83	  for (let i = at + WORD - 6; i < at + WORD; i++) n = n * 256 + (data[i] ?? 0);
 84	  return n;
 85	}
 86	
 87	function bytesAt(data: Uint8Array, at: number): Uint8Array {
 88	  const length = uint(data, at);
 89	  const start = at + WORD;
 90	  if (start + length > data.length) throw new GatewayError("bad-response", "return data is truncated");
 91	  return data.subarray(start, start + length);
 92	}
 93	
 94	/** Return data of `html()`: one ABI `string`, handed back as its raw bytes. */
 95	export function decodeString(data: Uint8Array): Uint8Array {
 96	  return bytesAt(data, uint(data, 0));
 97	}
 98	
 99	export interface RequestResult {
100	  status: number;
101	  body: Uint8Array;
102	  headers: [string, string][];
103	}
104	
105	/** Return data of ERC-5219 `request()`: `(uint16 statusCode, string body, KeyValue[] headers)`. */
106	export function decodeRequestResult(data: Uint8Array): RequestResult {
107	  const status = uint(data, 0);
108	  const body = bytesAt(data, uint(data, WORD));
109	  const list = uint(data, 2 * WORD);
110	  const count = uint(data, list);
111	  if (count > MAX_HEADERS) throw new GatewayError("bad-response", "too many headers");
112	  const base = list + WORD;
113	  const text = new TextDecoder("utf-8", { fatal: true });
114	  const headers: [string, string][] = [];
115	  try {
116	    for (let i = 0; i < count; i++) {
117	      const pair = base + uint(data, base + i * WORD);
118	      const key = bytesAt(data, pair + uint(data, pair));
119	      const value = bytesAt(data, pair + uint(data, pair + WORD));
120	      headers.push([text.decode(key), text.decode(value)]);
121	    }
122	  } catch (e) {
123	    if (e instanceof GatewayError) throw e;
124	    throw new GatewayError("bad-response", "header is not UTF-8");
125	  }
126	  return { status, body, headers };
127	}
128	import { hexToBytes } from "../../core/abi.ts";
129	import { GatewayError } from "../../core/errors.ts";
130	import { type Rpc, RpcRevert } from "../../core/ports.ts";
131	
132	/** Chain id to its JSON-RPC endpoints, tried in order. */
133	export type Chains = Readonly<Record<string, readonly string[]>>;
134	
135	export interface FetchRpcOptions {
136	  timeoutMs?: number;
137	  /** Cap on one JSON-RPC response body. The document arrives hex-encoded, so twice its size. */
138	  maxBytes?: number;
139	  fetch?: typeof fetch;
140	}
141	
142	interface JsonRpcReply {
143	  result?: unknown;
144	  error?: { code?: unknown; message?: unknown; data?: unknown };
145	}
146	
147	async function readCapped(res: Response, maxBytes: number): Promise<string> {
148	  if (!res.body) return "";
149	  const reader = res.body.getReader();
150	  const text = new TextDecoder();
151	  let out = "";
152	  let seen = 0;
153	  for (;;) {
154	    const { done, value } = await reader.read();
155	    if (done) return out + text.decode();
156	    seen += value.length;
157	    if (seen > maxBytes) {
158	      await reader.cancel();
159	      throw new Error("response exceeds the size cap");
160	    }
161	    out += text.decode(value, { stream: true });
162	  }
163	}
164	
165	/** A revert is the contract's answer; every other JSON-RPC error is the endpoint's problem. */
166	function isRevert(error: NonNullable<JsonRpcReply["error"]>): boolean {
167	  return error.code === 3 || (typeof error.message === "string" && /revert/i.test(error.message));
168	}
169	
170	/**
171	 * JSON-RPC over `fetch`, with ordered failover. Limits: one endpoint's word is taken as the chain's;
172	 * there is no quorum and no proof verification.
173	 *
174	 * `timeoutMs` bounds **one** endpoint, not the call. The endpoints are tried in order and nothing
175	 * spans the list, so with `n` endpoints a single `call` can take up to `n × timeoutMs` before it
176	 * throws `upstream` — at the defaults, two endpoints that never answer cost 20 s. Callers that need
177	 * a deadline across the whole list must impose it themselves; a budget here is M04's, not this
178	 * adapter's.
179	 */
180	export function createFetchRpc(chains: Chains, options: FetchRpcOptions = {}): Rpc {
181	  const { timeoutMs = 10_000, maxBytes = 16 * 1024 * 1024 } = options;
182	  const send = options.fetch ?? fetch;
183	
184	  async function callOne(endpoint: string, to: string, data: string): Promise<Uint8Array> {
185	    const res = await send(endpoint, {
186	      method: "POST",
187	      headers: { "content-type": "application/json" },
188	      body: JSON.stringify({ jsonrpc: "2.0", id: 1, method: "eth_call", params: [{ to, data }, "latest"] }),
189	      signal: AbortSignal.timeout(timeoutMs),
190	      credentials: "omit",
191	      cache: "no-store",
192	      referrerPolicy: "no-referrer",
193	    });
194	    /* A non-2xx body is not an answer, whatever it contains. Without this, a 429 or a 500 whose
195	       body happened to be JSON-RPC-shaped would be believed and failover would not happen. */
196	    if (!res.ok) throw new Error(`endpoint returned HTTP ${res.status}`);
197	    const text = await readCapped(res, maxBytes);
198	    const reply = JSON.parse(text) as JsonRpcReply;
199	    if (reply.error) {
200	      if (isRevert(reply.error)) throw new RpcRevert();
201	      throw new Error("endpoint returned an error");
202	    }
203	    if (typeof reply.result !== "string") throw new Error("endpoint returned no result");
204	    return hexToBytes(reply.result);
205	  }
206	
207	  return {
208	    supports: (chain) => (chains[chain]?.length ?? 0) > 0,
209	    async call(chain, to, data) {
210	      const endpoints = chains[chain] ?? [];
211	      if (endpoints.length === 0) throw new GatewayError("unknown-chain", `chain ${chain} is not configured`);
212	      for (const endpoint of endpoints) {
213	        try {
214	          return await callOne(endpoint, to, data);
215	        } catch (error) {
216	          if (error instanceof RpcRevert) throw error;
217	          // Deliberately swallowed: the next endpoint is the handling.
218	        }
219	      }
220	      throw new GatewayError("upstream", `no RPC endpoint for chain ${chain} answered`);
221	    },
222	  };
223	}
224	import { type Rpc, RpcRevert } from "../../core/ports.ts";
225	
226	/** `chain:address:calldata` to return data. A missing key reverts, as an unknown selector would. */
227	export type MemoryCalls = Map<string, Uint8Array>;
228	
229	export const memoryKey = (chain: string, to: string, data: string): string => `${chain}:${to}:${data}`;
230	
231	/** The local adapter: a complete `Rpc` over a map, and the contract every other adapter meets. */
232	export function createMemoryRpc(chainIds: string[], calls: MemoryCalls): Rpc {
233	  return {
234	    supports: (chain) => chainIds.includes(chain),
235	    async call(chain, to, data) {
236	      const out = calls.get(memoryKey(chain, to, data));
237	      if (out === undefined) throw new RpcRevert();
238	      return out;
239	    },
240	  };
241	}

