110	  const count = uint(data, list);
111	  if (count > MAX_HEADERS) throw new GatewayError("bad-response", "too many headers");
112	  const base = list + WORD;
113	  const text = new TextDecoder("utf-8", { fatal: true });
114	  const headers: [string, string][] = [];
115	  try {
116	    for (let i = 0; i < count; i++) {
117	      const pair = base + uint(data, base + i * WORD);
118	      const key = bytesAt(data, pair + uint(data, pair));
119	      const value = bytesAt(data, pair + uint(data, pair + WORD));
120	      headers.push([text.decode(key), text.decode(value)]);
121	    }
122	  } catch (e) {
123	    if (e instanceof GatewayError) throw e;
