132	/** Chain id to its JSON-RPC endpoints, tried in order. */
133	export type Chains = Readonly<Record<string, readonly string[]>>;
134	
135	export interface FetchRpcOptions {
136	  timeoutMs?: number;
137	  /** Cap on one JSON-RPC response body. The document arrives hex-encoded, so twice its size. */
138	  maxBytes?: number;
139	  fetch?: typeof fetch;
140	}
141	
142	interface JsonRpcReply {
143	  result?: unknown;
144	  error?: { code?: unknown; message?: unknown; data?: unknown };
145	}
146	
147	async function readCapped(res: Response, maxBytes: number): Promise<string> {
148	  if (!res.body) return "";
149	  const reader = res.body.getReader();
150	  const text = new TextDecoder();
151	  let out = "";
152	  let seen = 0;
153	  for (;;) {
154	    const { done, value } = await reader.read();
155	    if (done) return out + text.decode();
156	    seen += value.length;
157	    if (seen > maxBytes) {
158	      await reader.cancel();
159	      throw new Error("response exceeds the size cap");
160	    }
161	    out += text.decode(value, { stream: true });
162	  }
