165	/** A revert is the contract's answer; every other JSON-RPC error is the endpoint's problem. */
166	function isRevert(error: NonNullable<JsonRpcReply["error"]>): boolean {
167	  return error.code === 3 || (typeof error.message === "string" && /revert/i.test(error.message));
168	}
169	
170	/**
171	 * JSON-RPC over `fetch`, with ordered failover. Limits: one endpoint's word is taken as the chain's;
172	 * there is no quorum and no proof verification.
173	 *
174	 * `timeoutMs` bounds **one** endpoint, not the call. The endpoints are tried in order and nothing
175	 * spans the list, so with `n` endpoints a single `call` can take up to `n × timeoutMs` before it
176	 * throws `upstream` — at the defaults, two endpoints that never answer cost 20 s. Callers that need
177	 * a deadline across the whole list must impose it themselves; a budget here is M04's, not this
178	 * adapter's.
179	 */
180	export function createFetchRpc(chains: Chains, options: FetchRpcOptions = {}): Rpc {
181	  const { timeoutMs = 10_000, maxBytes = 16 * 1024 * 1024 } = options;
182	  const send = options.fetch ?? fetch;
183	
184	  async function callOne(endpoint: string, to: string, data: string): Promise<Uint8Array> {
185	    const res = await send(endpoint, {
186	      method: "POST",
187	      headers: { "content-type": "application/json" },
188	      body: JSON.stringify({ jsonrpc: "2.0", id: 1, method: "eth_call", params: [{ to, data }, "latest"] }),
189	      signal: AbortSignal.timeout(timeoutMs),
190	      credentials: "omit",
191	      cache: "no-store",
192	      referrerPolicy: "no-referrer",
193	    });
194	    /* A non-2xx body is not an answer, whatever it contains. Without this, a 429 or a 500 whose
195	       body happened to be JSON-RPC-shaped would be believed and failover would not happen. */
196	    if (!res.ok) throw new Error(`endpoint returned HTTP ${res.status}`);
197	    const text = await readCapped(res, maxBytes);
198	    const reply = JSON.parse(text) as JsonRpcReply;
199	    if (reply.error) {
200	      if (isRevert(reply.error)) throw new RpcRevert();
201	      throw new Error("endpoint returned an error");
202	    }
203	    if (typeof reply.result !== "string") throw new Error("endpoint returned no result");
204	    return hexToBytes(reply.result);
205	  }
206	
207	  return {
208	    supports: (chain) => (chains[chain]?.length ?? 0) > 0,
209	    async call(chain, to, data) {
210	      const endpoints = chains[chain] ?? [];
211	      if (endpoints.length === 0) throw new GatewayError("unknown-chain", `chain ${chain} is not configured`);
212	      for (const endpoint of endpoints) {
213	        try {
214	          return await callOne(endpoint, to, data);
215	        } catch (error) {
216	          if (error instanceof RpcRevert) throw error;
217	          // Deliberately swallowed: the next endpoint is the handling.
218	        }
219	      }
220	      throw new GatewayError("upstream", `no RPC endpoint for chain ${chain} answered`);
221	    },
222	  };
223	}
224	import { type Rpc, RpcRevert } from "../../core/ports.ts";
225	
226	/** `chain:address:calldata` to return data. A missing key reverts, as an unknown selector would. */
227	export type MemoryCalls = Map<string, Uint8Array>;
228	
229	export const memoryKey = (chain: string, to: string, data: string): string => `${chain}:${to}:${data}`;
230	
231	/** The local adapter: a complete `Rpc` over a map, and the contract every other adapter meets. */
232	export function createMemoryRpc(chainIds: string[], calls: MemoryCalls): Rpc {
233	  return {
234	    supports: (chain) => chainIds.includes(chain),
235	    async call(chain, to, data) {
236	      const out = calls.get(memoryKey(chain, to, data));
237	      if (out === undefined) throw new RpcRevert();
238	      return out;
239	    },
240	  };
241	}

