 75	    await new Promise<void>((done) => {
 76	      const channel = new MessageChannel();
 77	      channel.port1.onmessage = () => done();
 78	      registration.active?.postMessage(PURGE, [channel.port2]);
 79	      setTimeout(done, 1000);
 80	    });
