 98	 * because the bundler folds a boolean constant in both directions and so drops the parser each
 99	 * build does not use: comparing the object with null folds only the unpinned way, which left both
100	 * parsers in every bundle and cost the unpinned worker 570 bytes.
101	 */
102	declare const __GW44_PINNED__: boolean;
103	
104	export const CHAINS: Chains = __GW44_CHAINS__;
105	
106	/**
107	 * The one place either adapter decides which contract a URL names. A pinned build answers for its
108	 * configured contracts and reads no hostname; an unpinned build reads the two URL forms as before.
109	 */
110	export const targetOf: (url: URL) => Target | null = __GW44_PINNED__
111	  ? (url: URL) => pinnedTarget(url, __GW44_PINS__ as Pins)
112	  : parseTarget;
113	/** Reserved on every origin the gateway serves; a contract's own resource of this name is shadowed. */
114	export const SW_PATH = "/gw44-sw.js";
115	export const PURGE = "gw44:purge";
116	<!doctype html>
117	<html lang="en">
118	<head>
119	<meta charset="utf-8">
120	<meta name="viewport" content="width=device-width,initial-scale=1">
121	<meta name="robots" content="noindex">
122	<title>gw44</title>
123	</head>
124	<body>
125	<pre id="gw44">gw44: loading from chain…</pre>
126	<noscript><pre>gw44 reads this page from a contract in your browser, which needs JavaScript.</pre></noscript>
