130	/// <reference lib="webworker" />
131	import { errorResponse, resolve } from "../../core/resolve.ts";
132	import type { GatewayResponse } from "../../core/ports.ts";
133	import { createFetchRpc } from "../rpc/fetch.ts";
134	import { CHAINS, PURGE, targetOf } from "./config.ts";
135	
136	declare const self: ServiceWorkerGlobalScope;
137	
138	const rpc = createFetchRpc(CHAINS);
139	
140	function toResponse(r: GatewayResponse): Response {
141	  const nullBody = r.status === 204 || r.status === 205 || r.status === 304;
142	  return new Response(nullBody ? null : (r.body as Uint8Array<ArrayBuffer>), { status: r.status, headers: r.headers });
143	}
144	
145	async function handle(url: URL): Promise<Response> {
146	  try {
147	    const target = targetOf(url);
148	    if (target === null) return fetch(url);
149	    if (target.redirect !== undefined) {
150	      return Response.redirect(new URL(target.redirect, url), target.redirectStatus ?? 308);
151	    }
152	    return toResponse(await resolve(target, rpc));
153	  } catch (error) {
154	    return toResponse(errorResponse(error));
155	  }
156	}
