158	// A new worker replaces the old one at once: there is no cached state for the two to disagree on.
159	self.addEventListener("install", () => void self.skipWaiting());
160	self.addEventListener("activate", (event) => event.waitUntil(self.clients.claim()));
161	
162	self.addEventListener("fetch", (event) => {
163	  const url = new URL(event.request.url);
164	  // Not ours: the document's own traffic (its RPC, its wallet) and anything that is not a read.
165	  if (url.origin !== self.location.origin) return;
166	  if (event.request.method !== "GET" && event.request.method !== "HEAD") return;
167	  let named: boolean;
168	  try {
169	    named = targetOf(url) !== null;
170	  } catch {
171	    named = true; // malformed, but ours to answer
172	  }
173	  if (!named) return;
174	  event.respondWith(handle(url));
175	});
176	
177	// Nothing is cached yet, so there is nothing to purge. The message exists so the boot script's
178	// forced-reload path is already the one a cache will be cleared through.
179	self.addEventListener("message", (event) => {
180	  if (event.data === PURGE) event.ports[0]?.postMessage(true);
181	});
182	// Builds the whole deployable: dist/gw44-sw.js, dist/index.html and its copy dist/404.html.
183	//   node tools/build.ts            chains from ./chains.json, output to ./dist
184	//   GW44_CHAINS=… GW44_OUT=… node tools/build.ts
185	//   GW44_PIN=<chain>:<address>     one contract at every URL, that chain's endpoints only
186	//   GW44_CONFIG=gw44.json          one project's contract per chain, each under /<chain>/
187	import { createHash } from "node:crypto";
188	import { mkdir, readFile, readdir, writeFile } from "node:fs/promises";
189	import { build } from "esbuild";
190	import { type Pins, parsePin, parsePins } from "../src/core/target.ts";
191	
192	const out = process.env["GW44_OUT"] ?? "dist";
193	
194	/** Every configured contract, and which chain `/` goes to, so the log says what was built. */
195	function listing(pins: Pins): string {
196	  const each = Object.entries(pins.contracts)
197	    .map(([chain, address]) => `${chain}:${address}`)
198	    .join(" ");
199	  return Object.keys(pins.contracts).length === 1 ? each : `${each}, default ${pins.default}`;
200	}
201	
202	/** The deployable is these three files and nothing else; `gw44-sw.js` holds scope `/` at the root. */
203	const EXPECTED = ["404.html", "gw44-sw.js", "index.html"];
204	/** The worker is code every visitor of every contract executes, so its size is a gate, not a note. */
205	const SW_LIMIT = 16_384;
206	const chains = JSON.parse(await readFile(process.env["GW44_CHAINS"] ?? "chains.json", "utf8")) as unknown;
207	
208	/* The contracts are compiled in, like the endpoints: the bytes a visitor runs are the whole of what
209	   decides what is served. An unpinned build defines them as null and keeps every chain. */
210	const raw = process.env["GW44_PIN"] ?? "";
211	const configPath = process.env["GW44_CONFIG"] ?? "";
212	if (raw !== "" && configPath !== "") {
213	  throw new Error("GW44_PIN and GW44_CONFIG both set; a build serves one configuration, so pick one");
214	}
215	let pins: Pins | null = null;
216	let endpoints = chains;
217	if (raw !== "" || configPath !== "") {
218	  pins =
219	    configPath === "" ? parsePin(raw) : parsePins(JSON.parse(await readFile(configPath, "utf8")) as unknown);
220	  const all = chains as Record<string, unknown>;
221	  const only: Record<string, unknown> = {};
222	  for (const chain of Object.keys(pins.contracts)) {
223	    const endpointsFor = all[chain];
224	    if (endpointsFor === undefined) {
225	      const where = configPath === "" ? `pin ${raw}` : configPath;
226	      throw new Error(`${where} names chain ${chain}, which the chains file does not carry`);
227	    }
228	    only[chain] = endpointsFor;
229	  }
230	  endpoints = only;
231	}
232	
233	async function bundle(entry: string): Promise<string> {
234	  const result = await build({
235	    entryPoints: [entry],
236	    bundle: true,
237	    minify: true,
238	    format: "iife",
239	    target: "es2022",
240	    write: false,
241	    legalComments: "none",
242	    define: {
243	      __GW44_CHAINS__: JSON.stringify(endpoints),
244	      __GW44_PINS__: JSON.stringify(pins),
245	      // A boolean the bundler can fold both ways, so each build carries one parser and not two.
246	      __GW44_PINNED__: String(pins !== null),
247	    },
248	  });
249	  const file = result.outputFiles[0];
250	  if (file === undefined) throw new Error(`no output for ${entry}`);
251	  return file.text;
252	}
253	
254	const [sw, boot, shell] = await Promise.all([
255	  bundle("src/adapters/sw/sw.ts"),
256	  bundle("src/adapters/sw/boot.ts"),
257	  readFile("src/adapters/sw/shell.html", "utf8"),
258	]);
259	// A function replacement: a string one would expand `$&` and friends found in the minified script.
260	const page = shell.replace("/*@boot@*/", () => boot.replaceAll("</script", "<\\/script"));
261	
262	await mkdir(out, { recursive: true });
263	await Promise.all([
264	  writeFile(`${out}/gw44-sw.js`, sw),
265	  writeFile(`${out}/index.html`, page),
266	  // GitHub Pages serves 404.html for unknown paths; S3 and CloudFront are pointed at index.html.
267	  writeFile(`${out}/404.html`, page),
268	]);
269	/* The hashes are printed from the files on disk rather than from the strings above: what a reader
270	   wants to reproduce is the artefact, and a hash of the value in memory would not catch a write
271	   that changed it. Sorted by name so two runs are diffable line by line. */
272	const names = (await readdir(out)).sort();
273	const lines: string[] = [];
274	const sizes = new Map<string, number>();
275	for (const name of names) {
276	  const bytes = await readFile(`${out}/${name}`);
277	  sizes.set(name, bytes.length);
278	  lines.push(`${createHash("sha256").update(bytes).digest("hex")}  ${String(bytes.length).padStart(7)}  ${name}`);
279	}
280	console.log(pins === null ? `built ${out}/:` : `built ${out}/ (pinned to ${listing(pins)}):`);
281	for (const line of lines) console.log(`  ${line}`);
282	
283	const unexpected = names.filter((n) => !EXPECTED.includes(n));
284	if (unexpected.length > 0) {
285	  throw new Error(
286	    `${out}/ holds ${unexpected.join(", ")}; the deployable is only ${EXPECTED.join(", ")}; run 'make clean'`,
287	  );
288	}
289	/* The gate reads the bytes on disk, which the hash loop above already measured. `sw.length` is a
290	   string's length in UTF-16 units and equals the byte count only while the bundler emits ASCII,
291	   which is its default and not a thing this file asserts. */
292	const swBytes = sizes.get("gw44-sw.js");
293	if (swBytes === undefined) throw new Error(`${out}/ has no gw44-sw.js`);
294	if (swBytes > SW_LIMIT) {
295	  throw new Error(`gw44-sw.js is ${swBytes} B, over the ${SW_LIMIT} B limit`);
296	}

